+	private static boolean hasNonNullAnnotation(JCVariableDecl param) {
+		for (JCAnnotation ann : param.getModifiers().getAnnotations()) {
+			if (ann.getAnnotationType() instanceof JCFieldAccess) {
+				JCFieldAccess fa = (JCFieldAccess) ann.getAnnotationType();
+				if (fa.selected instanceof JCIdent && ((JCIdent) fa.selected).name.contentEquals("lombok") && fa.member.contentEquals("NonNull")) {
+					return true;
+				}
+			}
+			// Check for other non-null annotations
+			if (isNonNullAnnotation(ann)) {
+				return true;
+			}
+		}
+		return false;
+	}
+
+	private static boolean isNonNullAnnotation(JCAnnotation ann) {
+		// Simplified check for common non-null annotations
+		String annName = ann.getAnnotationType().toString();
+		return annName.equals("lombok.NonNull") ||
+		       annName.equals("javax.annotation.Nonnull") ||
+		       annName.equals("org.jetbrains.annotations.NotNull") ||
+		       annName.equals("org.eclipse.jdt.annotation.NonNull");
+	}
+
+	private static boolean isPrimitiveArrayType(Type type) {
+		return type != null && type.getKind() == TypeTag.ARRAY && type.hasTag(TypeTag.BYTE) ||
+		       type.hasTag(TypeTag.SHORT) || type.hasTag(TypeTag.INT) || type.hasTag(TypeTag.LONG) ||
+		       type.hasTag(TypeTag.FLOAT) || type.hasTag(TypeTag.DOUBLE) || type.hasTag(TypeTag.CHAR) ||
+		       type.hasTag(TypeTag.BOOLEAN);
+	}
